def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    rail_patches = image_patch.find("railing")
    man_patches = image_patch.find("man")

    if not rail_patches or not man_patches:
        return image_patch

    man_hand_center_x = sum([p.horizontal_center for p in man_patches]) / len(man_patches)

    under_rail = [r for r in rail_patches if r.vertical_center < man_hand_center_x]

    if not under_rail:
        return image_patch

    return min(under_rail, key=lambda r: abs(r.vertical_center - man_hand_center_x))

